if doc.custom_adjusted_qty and doc.custom_adjusted_qty > 0:
    doc.required_bom_qty = doc.custom_adjusted_qty
else:
    doc.required_bom_qty = doc.quantity

# Type: DocType Event
# Ref Doctype: Production Plan
# Trigger: on_cancel

def dbg(stage, docname, msg):
    frappe.msgprint(f"[{stage}] [{docname}] {msg}")

try:
    # find submitted Stock Entries that reference this Production Plan
    res = frappe.get_all("Stock Entry", filters={
        "custom_production_plan": doc.name,
        "docstatus": 1
    }, fields=["name"])

    if not res:
        frappe.msgprint("No linked submitted Stock Entries found for reversal.")
    else:
        for r in res:
            se_name = r.get("name")
            try:
                se = frappe.get_doc("Stock Entry", se_name)
                se.cancel()
                dbg("CANCEL", doc.name, f"Cancelled Stock Entry {se_name}")
            except Exception as inner_e:
                # log but continue cancelling others
                frappe.log_error(f"Failed to cancel {se_name}: {inner_e}", "Production Plan: cancel SE")

        frappe.msgprint("Linked Stock Entries processed for cancellation.")

except Exception as e:
    frappe.throw(f"[Cancel Error] {e}")
